  "action": {
    "tool": "write_file",
    "args": {
      "path": "src/stockflow/dead_stock.py",
      "content": "from __future__ import annotations
from typing import Iterable, List, Mapping, Dict
from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.parse_movement_line import parse_movement_line

def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    if idle_days < 1:
        raise ValueError("idle_days must be at least 1")

    filtered = [l.strip() for l in lines if l.strip() and not l.strip().startswith("#")]

    on_hand_by_loc = on_hand_by_location(filtered, case_sizes, as_of_day=today)
    sku_totals: Dict[str, int] = {}
    for (sku, loc), qty in on_hand_by_loc.items():
        sku_totals[sku] = sku_totals.get(sku, 0) + qty

    last_ship: Dict[str, int] = {}
    first_rcv: Dict[str, int] = {}
    for line in filtered:
        m = parse_movement_line(line, case_sizes)
        if m["day"] > today:
            continue
        sku, day = m["sku"], m["day"]
        if m["type"] == "SHP":
            if day > last_ship.get(sku, -1):
                last_ship[sku] = day
        elif m["type"] == "RCV":
            if "sku" in first_rcv or day < first_rcv.get(sku, float('inf')):
                if sku not in first_rcv or day < first_rcv[sku]:
                    first_rcv[sku] = day

    dead = []
    for sku, total in sku_totals.items():
        if total > 0:
            if sku in last_ship:
                ship_day = last_ship[sku]
                if today - ship_day >= idle_days:
                    dead.append(sku)
            elif sku in first_rcv:
                rcv_day = first_rcv[sku]
                if today - rcv_day >= idle_days:
                    dead.append(sku)

    return sorted(dead)"
    }
  },
  "messages": []
}
